    const amrex::Real qf = k_f * (sc[23] * sc[33]);
    const amrex::Real qr =
      k_f *
      (kc_fast ? (ge[33] * inv_ge[35] * ge[23] * inv_ge[16])
               : exp(-(-g_RT[16] + g_RT[23] + g_RT[33] - g_RT[35]))) *
      (sc[16] * sc[35]);
    const amrex::Real qdot = qf - qr;
    wdot[16] += qdot;
    wdot[23] -= qdot;
    wdot[33] -= qdot;
    wdot[35] += qdot;
